export function createQianhuGroveLayout(){
 const placements=authored.map(([id,species,variant,x,z,scale,yaw,drift])=>{
  const profile=profiles[variant??species],b=profile.bounds;
  const radius=species==='willow'?6.5:Math.hypot(Math.max(Math.abs(b.min[0]),Math.abs(b.max[0])),Math.max(Math.abs(b.min[2]),Math.abs(b.max[2])))*scale;
  return {id,species,...(variant?{variant}:{}),position:[x,null,z],scale,yaw,burial:.004,envelope:{radius,height:(species==='willow'?8.4:b.max[1])*scale},drift,
   sourceId:species==='willow'?'willow-root-continuum-r5':species==='low-broadleaf'?'court-low-broadleaf-r3':'jiuzhou-shore-understory-r4',
   historicalIndividual:false,evidence:'contemporary-exhibition-landscape',estimatedSourceTriangles:profile.triangles};
 });
 const ids=[...new Set(placements.filter(p=>p.species!=='low-broadleaf').map(p=>p.drift))];
 const regions=ids.map(id=>({id:'qianhu-'+id,placements:placements.filter(p=>p.drift===id&&p.species!=='low-broadleaf')}));
 regions.push({id:'qianhu-middle-source-region',placements:placements.filter(p=>p.species==='low-broadleaf')});
 for(const r of regions)r.estimatedFullSourceTriangles=r.placements.reduce((n,p)=>n+p.estimatedSourceTriangles,0);
 return {id:qianhuGrovePlanId,coordinateLayoutId:'front-court-three-buildings-r1',regions,buildingReserves:structuredClone(reservations),clearings:[],
  historicallySurveyed:false,nativeCompositionReviewed:false,actualRootVerticesChecked:false,
  integration:'Append shore regions to the existing Front owner; append these middle placements to its existing unique front-court-middle-shrubs source region. Do not instantiate a second owner.'};
}
